ValidationRule.errorConditionFormula:
AND(
     OR(
       AND(ISCHANGED(StageName),
           NOT(ISPICKVAL(PRIORVALUE(StageName),"Qualification")),
           ISPICKVAL(StageName, "Qualification")
       ),
       AND(ISNEW(),ISPICKVAL(StageName, "Qualification")
     )
   ),
   Not($Permission.QualifyOpp),
   Not($Permission.BypassValidations)
)
